#include <stdint.h>

#define GPIOA_BASE  0x40020000u
#define GPIOA_ODR   (*(volatile uint32_t *)(GPIOA_BASE + 0x14u))

void led_on(void) {
    GPIOA_ODR |= (1u << 5);     /* PA5 drives the user LED on many Nucleo boards */
}

#include <stdint.h>
#include <stdio.h>

/* Write `value` into a `width`-bit field at bit `pos`, keeping every other bit. */
static uint32_t field_set(uint32_t reg, unsigned pos, unsigned width, uint32_t value) {
    uint32_t mask = ((1u << width) - 1u) << pos;
    return (reg & ~mask) | ((value << pos) & mask);
}

int main(void) {
    uint32_t moder = 0x00000800u;              /* pin 5 currently 10: alternate function */
    moder = field_set(moder, 5 * 2, 2, 1u);    /* make pin 5 an output (01) */
    printf("0x%08X\n", (unsigned)moder);      /* prints 0x00000400 */

    uint32_t odr = 0x0Fu;
    odr ^= (1u << 1);                          /* toggle bit 1 */
    printf("0x%02X\n", (unsigned)odr);        /* prints 0x0D */
    return 0;
}

#include <stdint.h>

static volatile uint8_t data_ready;     /* written by the UART interrupt */
static volatile uint16_t ticks;         /* 16-bit counter, updated by a timer ISR */

void disable_irq(void);
void enable_irq(void);

void wait_for_data(void) {
    while (!data_ready) { }             /* volatile forces a fresh read every pass */
    data_ready = 0;
}

uint16_t read_ticks(void) {
    disable_irq();                      /* no torn read on an 8-bit CPU */
    uint16_t copy = ticks;
    enable_irq();
    return copy;
}

#include <stdint.h>

#define REG(addr)     (*(volatile uint32_t *)(addr))
#define RCC_AHB1ENR   REG(0x40023830u)
#define GPIOA_MODER   REG(0x40020000u)
#define GPIOA_PUPDR   REG(0x4002000Cu)
#define GPIOA_IDR     REG(0x40020010u)
#define GPIOA_BSRR    REG(0x40020018u)

void board_init(void) {
    RCC_AHB1ENR |= (1u << 0);              /* 1. clock for GPIOA on */
    GPIOA_MODER &= ~(3u << (5 * 2));       /* 2. PA5: clear both mode bits */
    GPIOA_MODER |=  (1u << (5 * 2));       /*    then 01 = output */
    GPIOA_MODER &= ~(3u << (0 * 2));       /* 3. PA0: 00 = input */
    GPIOA_PUPDR &= ~(3u << (0 * 2));
    GPIOA_PUPDR |=  (1u << (0 * 2));       /*    01 = pull-up */
}

void mirror_button(void) {
    if ((GPIOA_IDR & (1u << 0)) == 0) {    /* active low: 0 means pressed */
        GPIOA_BSRR = (1u << 5);            /* LED on */
    } else {
        GPIOA_BSRR = (1u << (5 + 16));     /* LED off */
    }
}

#include <stdint.h>

#define EXTI_PR (*(volatile uint32_t *)0x40013C14u)   /* STM32F4 pending register */

static volatile uint32_t button_presses;   /* written only by the ISR */

void EXTI0_IRQHandler(void) {               /* name must match the vector table */
    if (EXTI_PR & (1u << 0)) {
        EXTI_PR = (1u << 0);                /* write 1 to clear the pending flag */
        button_presses++;                   /* record it and leave */
    }
}

void toggle_led(void);

void main_loop(void) {
    uint32_t seen = 0;
    for (;;) {
        uint32_t now = button_presses;      /* one aligned 32-bit read: atomic on Cortex-M */
        if (now != seen) {
            seen = now;
            toggle_led();                   /* the real work happens here, not in the ISR */
        }
    }
}

#include <stdint.h>
#include <stdio.h>

/* Elapsed-time check that survives the 32-bit tick counter wrapping to 0. */
static int interval_passed(uint32_t now, uint32_t start, uint32_t interval) {
    return (uint32_t)(now - start) >= interval;
}

int main(void) {
    uint32_t start = 0xFFFFFF00u;    /* 256 ticks before the counter wraps */
    uint32_t now   = 0x00000010u;    /* 272 ticks later, after the wrap */

    printf("%d\n", interval_passed(now, start, 200));   /* 1: correct */
    printf("%d\n", now >= start + 200);                  /* 0: the naive check is wrong */
    return 0;
}

#include <stdint.h>
#include <stdio.h>

/* 12-bit ADC code to millivolts with integer math (no floating point needed). */
static uint32_t adc_to_mv(uint32_t code, uint32_t vref_mv) {
    return (code * vref_mv + 2047u) / 4095u;      /* +2047 rounds to nearest */
}

int main(void) {
    uint32_t arr = 999, ccr = 250;
    printf("duty %u%%\n", (unsigned)(ccr * 100u / (arr + 1u)));   /* duty 25% */
    printf("%u mV\n", (unsigned)adc_to_mv(2048, 3300));          /* 1651 mV */
    printf("%u mV\n", (unsigned)adc_to_mv(4095, 3300));          /* 3300 mV */
    return 0;
}

#include <stdint.h>

#define EVT_BUTTON  (1u << 0)
#define EVT_TICK    (1u << 1)

extern volatile uint32_t events;   /* bits set by ISRs */
void disable_irq(void);
void enable_irq(void);
void handle_button(void);
void update_display(void);
void watchdog_refresh(void);
void wait_for_interrupt(void);     /* wraps the WFI instruction */

void superloop(void) {
    for (;;) {
        disable_irq();
        uint32_t pending = events;  /* take and clear the flags atomically */
        events = 0;
        enable_irq();

        if (pending & EVT_BUTTON) handle_button();
        if (pending & EVT_TICK)   update_display();

        watchdog_refresh();         /* reached only while the loop keeps cycling */
        wait_for_interrupt();       /* sleep until the next event */
    }
}

